const q = $input.first().json.query || {};
const today = new Date().toISOString().split('T')[0];
return [{ json: { from: q.from || today, to: q.to || today } }];

const statsRow     = $('Get Stats').first()?.json || {};
const recent       = $('Get Recent Complaints').all().map(i => i.json);
const productivity = $('Get Productivity').all().map(i => i.json);

return [{ json: {
  success: true,
  stats: {
    totalLogged: parseInt(statsRow.total_logged || 0),
    escalated:   parseInt(statsRow.escalated    || 0),
    closed:      parseInt(statsRow.closed       || 0),
    edcsPending: parseInt(statsRow.edcs_pending || 0),
  },
  recentComplaints: recent,
  productivity
} }];
